#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>

#define MAX_TENANTS 64
#define MAX_PATH 512
#define STORAGE_ROOT "/var/tenants"

typedef struct {
    char tenant_id[64];
    char session_token[128];
    int is_authenticated;
    int privilege_level;
} tenant_ctx_t;

typedef struct {
    char path[MAX_PATH];
    struct stat st;
    int validated;
    int tenant_idx;
    int fd;
} file_request_t;

static pthread_mutex_t tenant_locks[MAX_TENANTS] = { [0 ... 63] = PTHREAD_MUTEX_INITIALIZER };

/* Validates that the resolved path belongs to the tenant's storage partition */
static int validate_tenant_path(const char *resolved, const char *tenant_id) {
    char expected_prefix[MAX_PATH];
    snprintf(expected_prefix, sizeof(expected_prefix), "%s/%s/", STORAGE_ROOT, tenant_id);
    return strncmp(resolved, expected_prefix, strlen(expected_prefix)) == 0;
}

/* Open, then validate via fd to eliminate TOCTOU */
static int open_and_validate(const char *input_path, const char *tenant_id, file_request_t *req) {
    char resolved[MAX_PATH];
    char fd_path[64];
    char fd_resolved[MAX_PATH];

    /* First open the file with O_NOFOLLOW on the final component via O_PATH */
    int fd = open(input_path, O_RDONLY | O_NOFOLLOW);
    if (fd < 0) {
        return -1;
    }

    /* Now resolve the path through /proc/self/fd to get the TRUE path of the opened fd */
    snprintf(fd_path, sizeof(fd_path), "/proc/self/fd/%d", fd);
    ssize_t len = readlink(fd_path, fd_resolved, sizeof(fd_resolved) - 1);
    if (len < 0) {
        close(fd);
        return -1;
    }
    fd_resolved[len] = '\0';

    /* Validate the actual opened file's path against tenant boundary */
    if (!validate_tenant_path(fd_resolved, tenant_id)) {
        close(fd);
        return -1;
    }

    strncpy(req->path, fd_resolved, MAX_PATH - 1);
    req->path[MAX_PATH - 1] = '\0';
    req->validated = 1;
    req->fd = fd;

    return 0;
}

/* Check file metadata to enforce per-tenant quota and type restrictions */
static int enforce_file_policy(file_request_t *req, tenant_ctx_t *ctx) {
    if (!req->validated || req->fd < 0) {
        return -1;
    }

    /* Use fstat on the already-opened fd — no TOCTOU possible */
    if (fstat(req->fd, &req->st) != 0) {
        return -1;
    }

    /* Only allow regular files */
    if (!S_ISREG(req->st.st_mode)) {
        return -1;
    }

    /* Enforce 10MB quota per file for non-admin tenants */
    if (ctx->privilege_level < 2 && req->st.st_size > 10 * 1024 * 1024) {
        return -1;
    }

    return 0;
}

/* Serve the file content to the requesting tenant using the already-opened fd */
static int serve_tenant_file(file_request_t *req, tenant_ctx_t *ctx, char *out_buf, size_t buf_sz) {
    ssize_t bytes_read;

    if (!req->validated || req->fd < 0) {
        return -1;
    }

    /* Guard against zero-sized buffer to avoid size_t underflow on buf_sz - 1 */
    if (out_buf == NULL || buf_sz == 0) {
        return -1;
    }

    /* Bounds-check tenant_idx before using it to index the lock array */
    if (req->tenant_idx < 0 || req->tenant_idx >= MAX_TENANTS) {
        return -1;
    }

    pthread_mutex_lock(&tenant_locks[req->tenant_idx]);

    /* Read directly from the validated fd — same file we checked */
    bytes_read = read(req->fd, out_buf, buf_sz - 1);
    if (bytes_read > 0) {
        out_buf[bytes_read] = '\0';
    }

    pthread_mutex_unlock(&tenant_locks[req->tenant_idx]);

    return (int)bytes_read;
}

/* Main request handler for file access */
int handle_file_request(const char *raw_path, tenant_ctx_t *ctx, int tenant_idx, char *response, size_t resp_sz) {
    file_request_t req;
    char constructed_path[MAX_PATH];

    memset(&req, 0, sizeof(req));
    req.tenant_idx = tenant_idx;
    req.fd = -1;

    /* Validate tenant_idx bounds up front to prevent out-of-bounds lock array access */
    if (tenant_idx < 0 || tenant_idx >= MAX_TENANTS) {
        snprintf(response, resp_sz, "HTTP/1.1 400 Bad Request\r\n\r\n");
        return -1;
    }

    if (!ctx->is_authenticated) {
        snprintf(response, resp_sz, "HTTP/1.1 401 Unauthorized\r\n\r\n");
        return -1;
    }

    /* Construct the full path within tenant's storage */
    snprintf(constructed_path, sizeof(constructed_path), "%s/%s/%s", STORAGE_ROOT, ctx->tenant_id, raw_path);

    /* Phase 1: Open and validate atomically via fd */
    if (open_and_validate(constructed_path, ctx->tenant_id, &req) != 0) {
        snprintf(response, resp_sz, "HTTP/1.1 403 Forbidden\r\n\r\n");
        return -1;
    }

    /* Phase 2: Enforce file policy using fstat on opened fd */
    if (enforce_file_policy(&req, ctx) != 0) {
        close(req.fd);
        snprintf(response, resp_sz, "HTTP/1.1 403 Policy Violation\r\n\r\n");
        return -1;
    }

    /* Phase 3: Serve the file from the same fd */
    int result = serve_tenant_file(&req, ctx, response, resp_sz);
    close(req.fd);

    if (result < 0) {
        snprintf(response, resp_sz, "HTTP/1.1 500 Internal Error\r\n\r\n");
        return -1;
    }

    return result;
}

/* Entry point for the web server worker thread */
void *worker_thread(void *arg) {
    tenant_ctx_t ctx;
    char response[4096];

    /* Simulated: in production, these come from parsed HTTP request */
    strncpy(ctx.tenant_id, "tenant_alpha", sizeof(ctx.tenant_id) - 1);
    ctx.tenant_id[sizeof(ctx.tenant_id) - 1] = '\0';
    strncpy(ctx.session_token, "valid_session_abc123", sizeof(ctx.session_token) - 1);
    ctx.session_token[sizeof(ctx.session_token) - 1] = '\0';
    ctx.is_authenticated = 1;
    ctx.privilege_level = 1;

    const char *requested_file = "documents/report.pdf";

    handle_file_request(requested_file, &ctx, 0, response, sizeof(response));

    return NULL;
}

int main(void) {
    pthread_t tid;
    pthread_create(&tid, NULL, worker_thread, NULL);
    pthread_join(tid, NULL);
    return 0;
}
